// This file is generated by AI.

// 报告工具: 列出 styles.css 里定义了、但源码中从未出现的类名 (只报告, 不是删除清单)。
// 用法: node scripts/find-dead-css.mjs
//
// 要删任何一条规则, 必须人工确认"模板 + 运行期拼出的类名"都不再需要它, 删完跑
// `node scripts/check-css-classes.mjs` —— 删错一条 CSS 是静默的界面损坏。
// 判据刻意保守 (源码里做**子串**匹配, 注释里提到的也算"被提到"), 宁可漏报也不误报。

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { editorRoot, walkFiles } from './walk.mjs';

const srcDir = join(editorRoot, 'src');
const css = readFileSync(join(srcDir, 'styles.css'), 'utf8');

const sources = walkFiles(srcDir)
  .filter((file) => /\.(ts|svelte|html)$/.test(file))
  .map((file) => readFileSync(file, 'utf8'))
  .join('\n');

/**
 * 类名是否被源码使用。
 *
 * 用"类名字符边界"匹配而不是裸 `includes`: 后者会被 `prompt-error` 这类更长名字的子串满足,
 * 把真正的死类名误判成活类名。
 */
function isUsed(name) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  /*
   * 右边界除了"非标识符字符"还要认 `{` 与 `$`: 运行期拼出的类名出现在模板表达式里
   * (`class="diag-sev-{severity}"`、`` `dialog-${size}` ``), 而这两个字符都不是标识符字符。
   */
  return new RegExp(`(^|[^A-Za-z0-9_-])${escaped}([^A-Za-z0-9_-]|$)`).test(sources);
}

/**
 * 类名是否**扩展**自某个模板表达式。
 *
 * 源码里写的是 `class="diag-sev-{severity}"`, 因此 `.diag-sev-1` 的对应片段是 `diag-sev-{`
 * 后跟 `{` 或 `$`。判据必须"由类名往短了找", 而不是"类名后面跟 `{`"。
 */
function isFromTemplate(name) {
  for (let length = name.length - 1; length >= 3; length -= 1) {
    const prefix = name.slice(0, length).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (new RegExp(`${prefix}[{$]`).test(sources)) return true;
  }
  return false;
}

// 从 CSS 里抽出类名: 只取 `.foo` 形式
const classes = new Set();
for (const match of css.matchAll(/\.(-?[A-Za-z_][A-Za-z0-9_-]*)/g)) {
  const name = match[1];
  if (/^\d/.test(name)) continue;
  classes.add(name);
}

const dead = [...classes].filter((name) => !isUsed(name) && !isFromTemplate(name)).sort();

// 变量: 统计定义处与引用处
const definedVars = new Set([...css.matchAll(/^\s*(--[a-z0-9-]+)\s*:/gm)].map((m) => m[1]));
const allCss = css;
const unusedVars = [...definedVars]
  .filter((name) => {
    // 在 CSS 里被 var() 用过?
    if (new RegExp(`var\\(\\s*${name}\\b`).test(allCss)) return false;
    // 在源码里被引用过 (内联 style / setProperty)?
    return !sources.includes(name);
  })
  .sort();

console.log(`CSS 里定义的选择器类名: ${classes.size}`);
console.log(`源码中找不到的类名: ${dead.length}`);
for (const name of dead) console.log(`  .${name}`);
console.log('');
console.log(`定义的 CSS 变量: ${definedVars.size}`);
console.log(`未被引用的变量: ${unusedVars.length}`);
for (const name of unusedVars) console.log(`  ${name}`);
